14	inline constexpr unsigned kDmiPollIterations = 1024;
15	
16	template<typename Bus>
17	void poll_until_set(Bus& bus, uint8_t reg, uint32_t mask,
18	                    const char* label = "poll_until_set")
19	{
20	  for (unsigned i = 0; i < kDmiPollIterations; ++i)
21	    if ((bus.read(reg) & mask) == mask) return;
22	  throw std::runtime_error(std::string{label} + ": timed out");
23	}
24	
25	template<typename Bus>
26	void poll_until_clear(Bus& bus, uint8_t reg, uint32_t mask,
27	                      const char* label = "poll_until_clear")
28	{
29	  for (unsigned i = 0; i < kDmiPollIterations; ++i)
30	    if ((bus.read(reg) & mask) == 0) return;
31	  throw std::runtime_error(std::string{label} + ": timed out");
32	}
