16	TEST_CASE("regno helpers map to spec ranges")
17	{
18	  CHECK(regno_csr(0x000) == 0x0000);
19	  CHECK(regno_csr(0x7C0) == 0x07C0);
20	  CHECK(regno_gpr(0)     == 0x1000);
21	  CHECK(regno_gpr(31)    == 0x101F);
22	  CHECK(regno_fpr(0)     == 0x1020);
23	  CHECK(regno_fpr(31)    == 0x103F);
24	  CHECK(regno_vector(0)  == 0x1040);
25	  CHECK(regno_vector(31) == 0x105F);
26	}
