28	TEST_CASE("write 64-bit GPR x10 = 0x1000 with transfer set")
29	{
30	  // cmdtype=0 (zero), aarsize=3 (64-bit) at [22:20], transfer=1 at [17],
31	  // write=1 at [16], regno=0x100A in [15:0].
32	  const auto cmd = access_register_command(regno_gpr(10), AarSize::Bits64,
33	                                           /*write=*/true);
34	  CHECK(((cmd >> 24) & 0xff) == 0u);                // cmdtype = AccessRegister
35	  CHECK(((cmd >> 20) & 0x7) == uint32_t(AarSize::Bits64));
36	  CHECK(((cmd >> 17) & 0x1) == 1u);                 // transfer
37	  CHECK(((cmd >> 16) & 0x1) == 1u);                 // write
38	  CHECK((cmd & 0xffff)      == 0x100Au);            // regno
39	}
